mkdir -p /tmp/bot-test-$$ && cd /tmp/bot-test-$$ && cat > check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decide } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g2-2/bot.mjs";

const mk = (over = {}) => ({ userId: "u1", category: "marketing", timezone: "Europe/Istanbul", quietStart: "22:00", quietEnd: "07:30", ...over });
const noQuiet = (over = {}) => mk({ quietStart: "00:00", quietEnd: "00:00", ...over });

// Istanbul is UTC+3, no DST. 12:00 local = 09:00Z.
const noon = new Date("2026-10-23T09:00:00Z");
assert.deepEqual(decide(mk(), noon), { send: true, rule: null });

// Transactional bypasses cap and quiet hours.
const u = "t1";
for (let i = 0; i < 3; i++) assert.deepEqual(decide(noQuiet({ userId: u }), noon), { send: true, rule: null });
assert.deepEqual(decide(noQuiet({ userId: u }), noon), { send: false, rule: "daily-cap" });
assert.deepEqual(decide(noQuiet({ userId: u, category: "transactional" }), noon), { send: true, rule: null });
assert.deepEqual(decide(mk({ userId: u, category: "transactional" }), new Date("2026-10-23T20:30:00Z")), { send: true, rule: null });

// Quiet hours wrap midnight: 22:00 local = 19:00Z; end exclusive 07:30 local = 04:30Z.
assert.equal(decide(mk({ userId: "q1" }), new Date("2026-10-23T19:00:00Z")).rule, "quiet-hours");
assert.equal(decide(mk({ userId: "q1" }), new Date("2026-10-24T01:30:00Z")).rule, "quiet-hours"); // 04:30 local
assert.deepEqual(decide(mk({ userId: "q1" }), new Date("2026-10-24T04:30:00Z")), { send: true, rule: null }); // 07:30 local
assert.deepEqual(decide(mk({ userId: "q2" }), new Date("2026-10-24T04:29:00Z")).rule, "quiet-hours"); // 07:29 local
// Quiet-blocked pushes do not consume cap.
for (let i = 0; i < 5; i++) decide(mk({ userId: "q3" }), new Date("2026-10-23T19:30:00Z"));
assert.deepEqual(decide(noQuiet({ userId: "q3" }), noon), { send: true, rule: null });

// Calendar day is customer-local. Istanbul 23:30 local on Oct 23 = 20:30Z Oct 23;
// 00:30 local Oct 24 = 21:30Z Oct 23. Cap resets at local midnight, not UTC.
const d = "d1";
const late = new Date("2026-10-23T20:30:00Z"); // Oct 23 23:30 local
for (let i = 0; i < 3; i++) assert.equal(decide(noQuiet({ userId: d, timezone: "Europe/Istanbul" }), late).send, true);
assert.equal(decide(noQuiet({ userId: d, timezone: "Europe/Istanbul" }), late).rule, "daily-cap");
assert.equal(decide(noQuiet({ userId: d, timezone: "Europe/Istanbul" }), new Date("2026-10-23T21:30:00Z")).send, true); // Oct 24 00:30 local

// Same instant, different zone: America/Los_Angeles is still Oct 23 at 20:30Z (13:30 local) -> cap shared per local day.
// DST: New York falls back 2026-11-01 at 02:00 local; the cap still uses local date strings.
const ny = { timezone: "America/New_York" };
assert.deepEqual(decide(noQuiet({ userId: "ny", ...ny }), new Date("2026-11-01T05:30:00Z")), { send: true, rule: null }); // 01:30 EDT Nov 1 (first occurrence)
assert.deepEqual(decide(noQuiet({ userId: "ny", ...ny }), new Date("2026-11-01T06:30:00Z")), { send: true, rule: null }); // 01:30 EST Nov 1

// Invalid inputs throw rather than silently sending.
assert.throws(() => decide(mk({ timezone: "Mars/Olympus" }), noon), RangeError);
assert.throws(() => decide(mk({ quietStart: "25:00" }), noon), TypeError);
assert.throws(() => decide(mk({ quietEnd: "7:30" }), noon), TypeError);
assert.throws(() => decide(mk({ category: "promo" }), noon), TypeError);
assert.throws(() => decide(mk(), new Date("nope")), TypeError);

// Equal start/end = empty window.
assert.deepEqual(decide(mk({ userId: "e1", quietStart: "10:00", quietEnd: "10:00" }), noon), { send: true, rule: null });
// Non-wrapping window 09:00-17:00 local (noon is inside).
assert.equal(decide(mk({ userId: "e2", quietStart: "09:00", quietEnd: "17:00" }), noon).rule, "quiet-hours");

console.log("all checks passed");
EOF
node check.mjs; echo "exit=$?"; node --version
